-- ==============================================================================
-- The Graticule Academic Geography Journal - Supabase Cloud Database Schema
-- Queen's University Belfast • Geography Society
-- ==============================================================================

-- 1. Authors Table
CREATE TABLE IF NOT EXISTS authors (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  title TEXT,
  affiliation TEXT,
  bio TEXT,
  avatar TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Posts Table (Articles, Essays, and Cartographic Dispatches)
CREATE TABLE IF NOT EXISTS posts (
  id SERIAL PRIMARY KEY,
  slug TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  subtitle TEXT,
  date TEXT NOT NULL,
  excerpt TEXT,
  content TEXT,
  cover_image TEXT,
  author TEXT NOT NULL,
  categories TEXT[] DEFAULT '{}',
  read_time TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. Submissions Table (Manuscripts submitted via /contact/ portal)
CREATE TABLE IF NOT EXISTS submissions (
  id SERIAL PRIMARY KEY,
  author_name TEXT NOT NULL,
  author_email TEXT NOT NULL,
  affiliation TEXT,
  article_title TEXT NOT NULL,
  category TEXT NOT NULL,
  abstract TEXT,
  file_name TEXT,
  file_size TEXT,
  status TEXT DEFAULT 'pending_review',
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. Enable Row Level Security (RLS)
ALTER TABLE authors ENABLE ROW LEVEL SECURITY;
ALTER TABLE posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE submissions ENABLE ROW LEVEL SECURITY;

-- 5. Public Policies (Allow read access to published journals, allow submission write)
CREATE POLICY "Allow public read access on authors" ON authors FOR SELECT USING (true);
CREATE POLICY "Allow public read access on posts" ON posts FOR SELECT USING (true);
CREATE POLICY "Allow public insert on submissions" ON submissions FOR INSERT WITH CHECK (true);

-- Allow full access for anon/authenticated API role during development & admin editing
CREATE POLICY "Allow all on authors for anon" ON authors FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all on posts for anon" ON posts FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow select on submissions for anon" ON submissions FOR SELECT USING (true);

-- 6. Indexes for Fast Filtering & Queries
CREATE INDEX IF NOT EXISTS idx_posts_slug ON posts(slug);
CREATE INDEX IF NOT EXISTS idx_posts_date ON posts(date);
CREATE INDEX IF NOT EXISTS idx_submissions_created_at ON submissions(created_at);

